// The path is a path. Council and batch come from the form, because they name
// the batch everything downstream is keyed on -- the input directory, the log,
// and later <council>-<batch>-full-mapping.csv -- and reading them out of fixed
// positions in the path only worked while every input sat under
// rmsiscratch/production/input/<Council>/Work Packages/<Batch>.
const source = String($json.source_path || '').trim().replace(/^\/+|\/+$/g, '');
const parts = source.split('/').filter(Boolean);
if (parts.length < 2) throw new Error('Source path must name a bucket and at least one prefix segment.');
if (parts.some(p => p === '.' || p === '..')) throw new Error('Source path must not contain . or .. segments.');
if (/[\x00-\x1f]/.test(source)) throw new Error('Source path must not contain control characters.');

const slug = value => String(value || '').trim().toLowerCase()
  .replace(/^work\s+package\s*/i, 'workpackage')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const council = slug($json.council);
const batch = slug($json.batch);
if (!council) throw new Error('Council is required and must contain letters or digits.');
if (!batch) throw new Error('Batch is required and must contain letters or digits.');

const bucket = parts[0];
const prefix = parts.slice(1).join('/') + '/';
const run_timestamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
return [{json:{
  source_path: source,
  bucket,
  prefix,
  council,
  batch,
  run_timestamp,
  destination: `/data/${council}/input-landmark/${batch}_${run_timestamp}`,
  report_directory: `/data/${council}/download_reports`,
  report_filename: `${council}_${batch}_initial_${run_timestamp}.json`,
}}];

const fs = require('fs');
const listed = $input.all().map(i => i.json);
const context = $('Parse and restrict path').first().json;
const files = listed.filter(x => x.Key);
const nested = files.filter(x => x.Key.slice(context.prefix.length).includes('/'));
if (files.length === 0) throw new Error('No files found at the approved S3 prefix.');
if (files.length > 10) throw new Error(`Unsafe source: ${files.length}+ files found; maximum is 10.`);
if (nested.length) throw new Error(`Unsafe source: subfolder content found (${nested.map(x => x.Key).join(', ')}).`);
fs.mkdirSync(context.destination, {recursive:true}); fs.mkdirSync(context.report_directory, {recursive:true});
return [{json: {...context, files: files.map(x => ({key:x.Key, size:x.Size, last_modified:x.LastModified}))}}];

const fs = require('fs'); const XLSX = require('@e965/xlsx');
const completed = $input.all(); const first = completed[0].json;
const files = completed.map(i => ({s3_key:i.json.files.key, local_path:i.json.fileName, size:i.json.files.size, last_modified:i.json.files.last_modified}));
const candidate = files.find(f => /\.xlsx?$/i.test(f.local_path)) || files.find(f => /\.json$/i.test(f.local_path));
if (!candidate) throw new Error('No JSON or XLSX source table was downloaded.');
let rows; if (/\.json$/i.test(candidate.local_path)) { const value = JSON.parse(fs.readFileSync(candidate.local_path, 'utf8')); rows = Array.isArray(value) ? value : (Array.isArray(value.data) ? value.data : []); } else { const workbook = XLSX.read(fs.readFileSync(candidate.local_path)); rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], {defval:null}); }
if (!Array.isArray(rows) || !rows.length) throw new Error('The selected source table contains no rows.');
const fields = [...new Set(rows.flatMap(row => Object.keys(row)))]; const missing = Object.fromEntries(fields.map(field => { const count = rows.filter(row => row[field] === null || row[field] === undefined || String(row[field]).trim() === '').length; return [field,{missing_count:count,missing_rate:Number((count/rows.length).toFixed(4))}]; }));
return [{json:{status:'downloaded',source_path:first.source_path,council:first.council,batch:first.batch,run_timestamp:first.run_timestamp,destination:first.destination,report_path:first.report_directory+'/'+first.report_filename,downloaded_files:files,downloaded_file_count:files.length,table_file:candidate.local_path,case_count:rows.length,table_fields:fields,field_missing_distribution:missing,table_head_20:rows.slice(0,20)}}];
